// ============================================================
// ENDVOUR – OpenCode Free Usage Limit Bypass Plugin
// ============================================================
// This plugin injects the official OpenCode client headers
// to bypass the 429 FreeUsageLimitError.
// ============================================================

/**
 * Endvour plugin – bypasses OpenCode Zen free usage limits
 * @param {Object} ctx - OpenCode plugin context
 * @returns {Object} Plugin hooks
 */
export default async function endvour(ctx) {
  console.log('[Endvour] 🚀 Initializing Endvour plugin...');
  console.log('[Endvour] 📦 Version 1.0.0');

  // ─── CONFIG ──────────────────────────────────────────────
  const CONFIG = {
    // Official User-Agent string (matches OpenCode CLI)
    userAgent: 'opencode/1.15.5 ai-sdk/provider-utils/4.0.23 runtime/bun/1.3.14',
    
    // Official client headers
    headers: {
      'x-opencode-client': 'cli',
      'x-opencode-project': 'global',
      // Session and request IDs are generated per request
    },
    
    // Enable debug logging
    debug: process.env.ENDVOUR_DEBUG === 'true' || false,
  };

  // ─── GENERATE RANDOM IDS ──────────────────────────────
  function generateId(prefix, length = 12) {
    const chars = 'abcdefghijklmnopqrstuvwxyz0123456789';
    let result = '';
    for (let i = 0; i < length; i++) {
      result += chars.charAt(Math.floor(Math.random() * chars.length));
    }
    return `${prefix}_${result}`;
  }

  // ─── LOGGING ────────────────────────────────────────────
  function log(...args) {
    if (CONFIG.debug) {
      console.log('[Endvour]', ...args);
    }
  }

  // ─── PLUGIN HOOKS ──────────────────────────────────────
  return {
    /**
     * Hook: Intercept and modify chat request parameters
     * This adds the official headers to every LLM request
     */
    'chat.params': async (input, output) => {
      log('📨 Intercepting chat request...');
      log('  → Model:', input.model);
      log('  → Provider:', input.provider);

      // Generate session and request IDs
      const sessionId = generateId('ses', 16);
      const requestId = generateId('msg', 16);

      // ─── INJECT HEADERS ──────────────────────────────
      if (!output.headers) {
        output.headers = {};
      }

      // Override User-Agent with official one
      output.headers['User-Agent'] = CONFIG.userAgent;
      
      // Add official OpenCode client headers
      output.headers['x-opencode-client'] = 'cli';
      output.headers['x-opencode-session'] = sessionId;
      output.headers['x-opencode-project'] = 'global';
      output.headers['x-opencode-request'] = requestId;

      log('✅ Headers injected:');
      log('  → User-Agent:', CONFIG.userAgent);
      log('  → x-opencode-session:', sessionId);
      log('  → x-opencode-request:', requestId);

      return output;
    },

    /**
     * Hook: Intercept and modify the request body
     * This can be used to add additional parameters if needed
     */
    'chat.body': async (input, output) => {
      log('📦 Intercepting chat body...');
      
      // You can modify the request body here if needed
      // For example, force a specific model or add custom parameters
      
      log('✅ Body processed');
      return output;
    },

    /**
     * Hook: Log successful responses
     */
    'chat.response': async (input, output) => {
      log('📬 Chat response received');
      log('  → Status:', output.status);
      log('  → Tokens used:', output.usage?.totalTokens || 'unknown');
      
      return output;
    },

    /**
     * Hook: Handle errors (including 429)
     */
    'chat.error': async (input, error) => {
      if (error.status === 429) {
        console.warn('[Endvour] ⚠️ 429 Rate limit detected – headers were not applied correctly?');
        console.warn('[Endvour] 💡 Try restarting OpenCode with --debug flag');
      } else {
        console.error('[Endvour] ❌ Chat error:', error.message);
      }
      return error;
    },

    /**
     * Hook: Register a custom slash command
     */
    'command': {
      'endvour': {
        description: 'Endvour plugin commands',
        handler: async (args) => {
          const subcommand = args[0] || 'help';
          
          switch (subcommand) {
            case 'status':
              console.log('[Endvour] 📊 Status:');
              console.log(`  → Version: 1.0.0`);
              console.log(`  → Debug: ${CONFIG.debug}`);
              console.log(`  → User-Agent: ${CONFIG.userAgent}`);
              console.log(`  → Headers:`, CONFIG.headers);
              break;
              
            case 'debug':
              CONFIG.debug = !CONFIG.debug;
              console.log(`[Endvour] 🐛 Debug mode: ${CONFIG.debug ? 'ON' : 'OFF'}`);
              break;
              
            case 'help':
            default:
              console.log('[Endvour] 📖 Commands:');
              console.log('  /endvour status   - Show plugin status');
              console.log('  /endvour debug    - Toggle debug mode');
              console.log('  /endvour help     - Show this help');
              break;
          }
        }
      }
    }
  };
}
